import ghidra.app.decompiler.*; import ghidra.app.script.GhidraScript; import ghidra.program.model.address.*; import ghidra.program.model.listing.*; import ghidra.program.model.symbol.*;
public class WatchBot150Callers extends GhidraScript { public void run()throws Exception{DecompInterface d=new DecompInterface();d.openProgram(currentProgram);Function f=getFunctionAt(toAddr(0x00496c60L));println("TARGET "+f);ReferenceIterator it=getReferencesTo(f.getEntryPoint());int n=0;while(it.hasNext()&&n++<20){Reference r=it.next();Function c=getFunctionContaining(r.getFromAddress());println("CALLER "+r.getFromAddress()+" "+(c==null?"<none>":c.getName()));if(c!=null){DecompileResults z=d.decompileFunction(c,100,monitor);if(z.getDecompiledFunction()!=null)println(z.getDecompiledFunction().getC());}}d.dispose();}}
